package gogocodec

import (
	"fmt"

	"google.golang.org/protobuf/encoding/protowire"
)

// maxNestingDepth is the recursion limit protobuf-go applies when it decodes a message. Decoders
// generated by gogo recurse once per nested message and track no depth, so the codec applies the
// same limit to their input before they run.
const maxNestingDepth = protowire.DefaultRecursionLimit

var errNestedTooDeeply = fmt.Errorf("proto: message nests more than %d levels deep", maxNestingDepth)

// generatedUnmarshaler is implemented by messages generated by gogo, whose Unmarshal recurses
// without a depth limit, including those that protobuf-go decodes through that same method.
type generatedUnmarshaler interface {
	XXX_Unmarshal([]byte) error
}

func checkNesting(data []byte) error {
	if nestsDeeperThan(data, maxNestingDepth) {
		return errNestedTooDeeply
	}
	return nil
}

// nestsDeeperThan reports whether data, read as a protobuf message, holds length-delimited fields
// nested more than limit deep. Without a schema it cannot tell a nested message from a string or
// bytes field, so it reads every length-delimited field as a message for as far as it parses, and
// at the first malformed byte resumes after that field in the enclosing one. A generated decoder
// only descends into a field of its own message type, and only once every field before it has
// decoded, so this never reports less nesting than a decoder would recurse through. It parses
// varints and skips groups as leniently as the gogo-generated decoders do, because a sibling the
// scan stopped short of could otherwise still be decoded. It reads each byte once and keeps one
// offset per open level, so it uses no recursion and at most limit offsets of memory.
func nestsDeeperThan(data []byte, limit int) bool {
	var parentEnds []int
	end := len(data)
	for i := 0; ; {
		if i == end {
			if len(parentEnds) == 0 {
				return false
			}
			end = parentEnds[len(parentEnds)-1]
			parentEnds = parentEnds[:len(parentEnds)-1]
			continue
		}
		tag, n := consumeVarint(data[i:end])
		if n == 0 {
			i = end
			continue
		}
		i += n
		if protowire.Type(tag&7) != protowire.BytesType {
			n = skipValue(data[i:end], protowire.Type(tag&7))
			if n < 0 {
				i = end
			} else {
				i += n
			}
			continue
		}
		length, n := consumeLength(data[i:end])
		if n == 0 {
			i = end
			continue
		}
		if len(parentEnds) == limit {
			return true
		}
		parentEnds = append(parentEnds, end)
		i += n
		end = i + length
	}
}

// skipValue returns the length of a value of wire type typ, other than a length-delimited one, at
// the start of b, or -1 if b does not hold one that a gogo-generated decoder would skip. A group
// is skipped whole, as those decoders skip it, without reading its fields as nested messages.
func skipValue(b []byte, typ protowire.Type) int {
	groupDepth := 0
	i := 0
	for {
		switch typ {
		case protowire.VarintType:
			_, n := consumeVarint(b[i:])
			if n == 0 {
				return -1
			}
			i += n
		case protowire.Fixed64Type:
			i += 8
		case protowire.Fixed32Type:
			i += 4
		case protowire.BytesType:
			length, n := consumeLength(b[i:])
			if n == 0 {
				return -1
			}
			i += n + length
		case protowire.StartGroupType:
			groupDepth++
		case protowire.EndGroupType:
			if groupDepth == 0 {
				return -1
			}
			groupDepth--
		default:
			return -1
		}
		if i > len(b) {
			return -1
		}
		if groupDepth == 0 {
			return i
		}
		tag, n := consumeVarint(b[i:])
		if n == 0 {
			return -1
		}
		i += n
		typ = protowire.Type(tag & 7)
	}
}

// consumeVarint reads a varint the way gogo-generated decoders do: at most ten bytes, with any
// bits past the 64th dropped rather than refused. It returns n == 0 if b holds no such varint.
func consumeVarint(b []byte) (v uint64, n int) {
	if len(b) > 0 && b[0] < 0x80 {
		return uint64(b[0]), 1
	}
	for shift := uint(0); shift < 64; shift += 7 {
		if n == len(b) {
			return 0, 0
		}
		c := b[n]
		n++
		v |= uint64(c&0x7F) << shift
		if c < 0x80 {
			return v, n
		}
	}
	return 0, 0
}

// consumeLength reads the length of a length-delimited value the way gogo-generated decoders do,
// as a varint into an int that must not be negative. It returns n == 0 if b holds no such varint
// or the value it gives the length of runs past the end of b.
func consumeLength(b []byte) (length, n int) {
	for shift := uint(0); shift < 64; shift += 7 {
		if n == len(b) {
			return 0, 0
		}
		c := b[n]
		n++
		length |= int(c&0x7F) << shift
		if c < 0x80 {
			if length < 0 || length > len(b)-n {
				return 0, 0
			}
			return length, n
		}
	}
	return 0, 0
}
